import {dateAt} from './model.mjs';
import {seasonNames} from './registry.mjs';
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const dateLabel=(d,s)=>{const a=dateAt(d,s);return `${a.day} ${({spring:'весны',summer:'лета',fall:'осени',winter:'зимы'})[a.season]}, год ${a.year}`};
const fmt=n=>n.toLocaleString('ru-RU',{maximumFractionDigits:1});
export function profitChart(raw,processed,s){
 const w=globalThis.matchMedia?.('(max-width:600px)').matches?430:820,h=220,pad={l:62,r:22,t:20,b:35},all=[...raw,...(processed||[])].map(e=>e.profit),min=Math.min(0,...all),max=Math.max(1,...all),span=max-min||1;
 const x=i=>pad.l+(w-pad.l-pad.r)*(raw.length===1?.5:i/(raw.length-1)),y=v=>pad.t+(h-pad.t-pad.b)*(max-v)/span;
 const path=data=>data.map((e,i)=>`${i?'H':'M'}${x(i).toFixed(2)}${i?'V':' '}${y(e.profit).toFixed(2)}`).join(' ');
 const grids=Array.from({length:5},(_,i)=>{const v=min+span*i/4;return `<g><line x1="${pad.l}" x2="${w-pad.r}" y1="${y(v)}" y2="${y(v)}" stroke="#e5eadf"/><text x="${pad.l-10}" y="${y(v)+4}" text-anchor="end">${fmt(v)}g</text></g>`}).join('');
 const indices=[...new Set([0,Math.floor((raw.length-1)/3),Math.floor((raw.length-1)*2/3),raw.length-1])];
 return `<svg class="profit-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Накопленная прибыль с одной посадочной единицы по дням. От ${fmt(min)} до ${fmt(max)} золота.">${grids}<line x1="${pad.l}" x2="${w-pad.r}" y1="${y(0)}" y2="${y(0)}" stroke="#b8c6aa" stroke-dasharray="4 4"/>${processed?`<path d="${path(processed)}" fill="none" stroke="#b49655" stroke-width="2" stroke-dasharray="5 3"/>`:''}<path d="${path(raw)}" fill="none" stroke="#618344" stroke-width="2.5"/>${raw.filter(e=>e.revenue||e.expense).map(e=>{const i=raw.indexOf(e);return `<circle cx="${x(i)}" cy="${y(e.profit)}" r="3" fill="#618344"><title>${escape(dateLabel(e.day,s))}: ${fmt(e.profit)}g</title></circle>`}).join('')}${indices.map(i=>{const d=dateAt(raw[i].day,s);return `<text x="${x(i)}" y="${h-10}" text-anchor="middle">${d.day} ${seasonNames[d.season].toLowerCase()}</text>`}).join('')}</svg>`;
}
export function cropCalendar(c,r,s){
 const months=[];for(let m=0;m<s.horizon;m++){
 const d=dateAt(m*28+1,s);months.push(`<div class="month"><h4>${seasonNames[d.season]} <small>год ${d.year}</small></h4><div class="month-week">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(x=>`<span>${x}</span>`).join('')}</div><div class="month-grid">${Array.from({length:28},(_,i)=>{const day=m*28+i+1,harvest=r.dates.includes(day),plant=r.plantings.includes(day),inWindow=day>=s.day,growing=inWindow&&day>=r.start&&!harvest&&(r.dates.some(x=>x>day)||day<r.start+r.grow),regrowing=growing&&r.dates.some(x=>x<day);const status=harvest?(r.variants?'возможный сбор':'сбор урожая'):plant?'посадка':c.stochastic&&!r.existing?'случайный рост':regrowing?'повторный рост':growing?'рост':'пусто';return `<div class="month-day ${!inWindow?'past':''} ${harvest?'harvest':growing?'growing':''} ${plant?'planted':''}" title="${escape(dateLabel(day,s)+': '+status)}"><span>${i+1}</span>${harvest&&c.image?`<img src="${escape(c.image)}" alt="${r.variants?'Возможный сбор':'Сбор'}">`:harvest?'<b>✓</b>':plant?'<b>↓</b>':growing?'<i></i>':''}</div>`}).join('')}</div></div>`)}return `<div class="months">${months.join('')}</div><div class="calendar-key"><span><i class="key-plant"></i>Посадка</span><span><i class="key-grow"></i>Рост / повторный рост</span><span><i class="key-harvest"></i>${r.variants?'Возможный сбор':'Сбор'}</span></div>`;
}
